<?php
declare(strict_types=1);
// Self-contained, server-side SQLite demo commerce. Does not process payments.
require_once __DIR__.'/bootstrap.php';
function demo_db(): PDO {
 static $pdo;
 if($pdo instanceof PDO) return $pdo;
 if(!extension_loaded('pdo_sqlite')) throw new RuntimeException('PHP pdo_sqlite extension is required for automatic demo setup. Enable it in cPanel PHP Selector.');
 $root=dirname(__DIR__,3).'/stryde-demo-private';
 if(!is_dir($root) && !mkdir($root,0700,true) && !is_dir($root)) throw new RuntimeException('Cannot create private data directory outside public_html.');
 $path=$root.'/store.sqlite';
 $pdo=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
 $pdo->exec('PRAGMA busy_timeout=5000; PRAGMA foreign_keys=ON;');
 $pdo->exec("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,description TEXT,price_cents INTEGER NOT NULL,active INTEGER DEFAULT 1);
 CREATE TABLE IF NOT EXISTS variants(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,size_us TEXT NOT NULL,colorway TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 10,UNIQUE(product_id,size_us,colorway));
 CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,public_id TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'demo',payment_status TEXT NOT NULL DEFAULT 'demo',subtotal_cents INTEGER NOT NULL,shipping_cents INTEGER NOT NULL,estimated_tax_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,shipping_method TEXT NOT NULL,shipping_json TEXT NOT NULL,tracking_carrier TEXT DEFAULT '',tracking_number TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id INTEGER NOT NULL,variant_id INTEGER NOT NULL,name TEXT NOT NULL,size_us TEXT NOT NULL,colorway TEXT NOT NULL,finish TEXT NOT NULL,materials_json TEXT,quantity INTEGER NOT NULL,price_cents INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS store_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,key_hash TEXT NOT NULL,attempted_at INTEGER NOT NULL);");
 $seed=[['aerodyne','AERODYNE ONE',22000,['solar','ice','volt','violet']],['volt','VOLT PRO',24500,['solar']],['nexus','NEXUS',21000,['ice']],['phantom','PHANTOM',23000,['violet']]];
 foreach($seed as [$sku,$name,$price,$colors]){
  $pdo->prepare('INSERT OR IGNORE INTO products(sku,name,description,price_cents) VALUES(?,?,?,?)')->execute([$sku,$name,'Demo concept sneaker',$price]);
  $pid=(int)$pdo->query('SELECT id FROM products WHERE sku='.$pdo->quote($sku))->fetchColumn();
  foreach($colors as $color)foreach(['7','8','9','10','11','12'] as $size)$pdo->prepare('INSERT OR IGNORE INTO variants(product_id,size_us,colorway,stock) VALUES(?,?,?,10)')->execute([$pid,$size,$color]);
 }
 foreach(['standard_cents'=>'1500','express_cents'=>'2900','free_threshold_cents'=>'15000','estimated_tax_rates'=>json_encode(['AB'=>.05,'BC'=>.12,'MB'=>.12,'NB'=>.15,'NL'=>.15,'NS'=>.14,'NT'=>.05,'NU'=>.05,'ON'=>.13,'PE'=>.15,'QC'=>.14975,'SK'=>.11,'YT'=>.05])] as $k=>$v)$pdo->prepare('INSERT OR IGNORE INTO store_settings(setting_key,setting_value) VALUES(?,?)')->execute([$k,$v]);
 @chmod($path,0600);return $pdo;
}
function demo_user(): ?array {if(empty($_SESSION['demo_uid']))return null;$q=demo_db()->prepare('SELECT id,name,email,role,created_at FROM users WHERE id=?');$q->execute([$_SESSION['demo_uid']]);return $q->fetch()?:null;}
function demo_admin(): array {$u=demo_user();if(!$u||$u['role']!=='admin')api_error('Administrator only',403);return $u;}
function demo_setting(string $key,string $fallback): string {$q=demo_db()->prepare('SELECT setting_value FROM store_settings WHERE setting_key=?');$q->execute([$key]);return (string)($q->fetchColumn()?:$fallback);}
function demo_quote(array $items,string $province,string $shippingMethod): array {
 if(!in_array($shippingMethod,['standard','express'],true))api_error('Invalid shipping method');
 if(!preg_match('/^[A-Z]{2}$/',$province))api_error('Choose province');
 if(count($items)<1||count($items)>30)api_error('Add an item to the shopping bag');
 $lines=[];$sub=0;$totals=[];$select=demo_db()->prepare('SELECT p.id product_id,p.name,p.price_cents,v.id variant_id,v.stock FROM products p JOIN variants v ON v.product_id=p.id WHERE p.sku=? AND v.size_us=? AND v.colorway=? AND p.active=1');
 foreach($items as $item){if(!is_array($item))api_error('Invalid item');$sku=(string)($item['id']??'');$size=(string)($item['size']??'');$color=(string)($item['color']??'solar');$qty=filter_var($item['qty']??null,FILTER_VALIDATE_INT);if(!in_array($size,['7','8','9','10','11','12'],true)||!$qty||$qty<1||$qty>10)api_error('Invalid size or quantity');$select->execute([$sku,$size,$color]);$r=$select->fetch();if(!$r)api_error('Selected sneaker is unavailable');$vid=(int)$r['variant_id'];$totals[$vid]=($totals[$vid]??0)+$qty;if($totals[$vid]>(int)$r['stock'])api_error('Not enough demo stock');$finish=(string)($item['finish']??'reflective');if(!in_array($finish,['matte','reflective'],true))api_error('Invalid finish');$materials=$item['materials']??null;if($materials!==null&&!is_array($materials))api_error('Invalid materials');$lines[]=['product_id'=>(int)$r['product_id'],'variant_id'=>$vid,'name'=>$r['name'],'size'=>$size,'color'=>$color,'finish'=>$finish,'materials'=>$materials,'quantity'=>$qty,'unit_cents'=>(int)$r['price_cents']];$sub+=$qty*(int)$r['price_cents'];}
 $standard=(int)demo_setting('standard_cents','1500');$express=(int)demo_setting('express_cents','2900');$threshold=(int)demo_setting('free_threshold_cents','15000');$ship=$shippingMethod==='express'?$express:($sub>=$threshold?0:$standard);$rates=json_decode(demo_setting('estimated_tax_rates','{}'),true)?:[];$rate=(float)($rates[$province]??.05);$tax=(int)round(($sub+$ship)*$rate);
 return ['lines'=>$lines,'subtotal_cents'=>$sub,'shipping_cents'=>$ship,'estimated_tax_cents'=>$tax,'total_cents'=>$sub+$ship+$tax,'shipping_method'=>$shippingMethod,'tax_disclaimer'=>'Illustrative demo estimate; not a tax invoice.','currency'=>'CAD'];
}
