 if($a==='register'&&$method==='POST'){$b=body_json();$name=trim((string)($b['name']??''));$email=strtolower(trim((string)($b['email']??'')));$pw=(string)($b['password']??'');if(mb_strlen($name)<2||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<12||strlen($pw)>256)api_error('Enter a name, valid email and password (12+ characters)');try{$db->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'customer')")->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);}catch(PDOException $e){api_error('Email is already registered',409);}session_regenerate_id(true);$_SESSION['demo_uid']=(int)$db->lastInsertId();$_SESSION['csrf']=bin2hex(random_bytes(24));json_response(['user'=>demo_user(),'csrf'=>$_SESSION['csrf']],201);}
 if($a==='login'&&$method==='POST'){$b=body_json();$email=strtolower(trim((string)($b['email']??'')));$pw=(string)($b['password']??'');$key=hash('sha256',$email.'|'.($_SERVER['REMOTE_ADDR']??''));$db->prepare('DELETE FROM login_attempts WHERE attempted_at < ?')->execute([time()-900]);$q=$db->prepare('SELECT COUNT(*) FROM login_attempts WHERE key_hash=?');$q->execute([$key]);if((int)$q->fetchColumn()>=7)api_error('Too many attempts, try again later.',429);$q=$db->prepare('SELECT id,password_hash FROM users WHERE email=?');$q->execute([$email]);$found=$q->fetch();if(!$found||!password_verify($pw,$found['password_hash'])){$db->prepare('INSERT INTO login_attempts(key_hash,attempted_at) VALUES(?,?)')->execute([$key,time()]);api_error('Incorrect email or password',401);} $db->prepare('DELETE FROM login_attempts WHERE key_hash=?')->execute([$key]);session_regenerate_id(true);$_SESSION['demo_uid']=(int)$found['id'];$_SESSION['csrf']=bin2hex(random_bytes(24));json_response(['user'=>demo_user(),'csrf'=>$_SESSION['csrf']]);}
 if($a==='logout'&&$method==='POST'){$_SESSION=[];session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(24));json_response(['logged_out'=>true,'csrf'=>$_SESSION['csrf']]);}
 if($a==='quote'&&$method==='POST'){$b=body_json();json_response(demo_quote($b['items']??[],strtoupper((string)($b['province']??'BC')),(string)($b['shipping_method']??'standard')));}
 if($a==='checkout'&&$method==='POST'){
  if(!$u)api_error('Sign in to place a demo order',401);$b=body_json();$address=trim((string)($b['address']??''));$city=trim((string)($b['city']??''));$postal=trim((string)($b['postal_code']??''));$recipient=trim((string)($b['recipient']??''));$province=strtoupper((string)($b['province']??''));if(strlen($address)<5||strlen($city)<2||strlen($postal)<3||strlen($recipient)<2||strlen($address)>190||strlen($recipient)>120)api_error('Complete shipping details');$quote=demo_quote($b['items']??[],$province,(string)($b['shipping_method']??'standard'));$public='DEMO-'.strtoupper(bin2hex(random_bytes(5)));$shipping=['address'=>$address,'city'=>$city,'postal_code'=>$postal,'recipient'=>$recipient,'province'=>$province,'country'=>'CA'];$db->beginTransaction();try{$q=$db->prepare("INSERT INTO orders(public_id,user_id,status,payment_status,subtotal_cents,shipping_cents,estimated_tax_cents,total_cents,shipping_method,shipping_json) VALUES(?,?,'demo','demo',?,?,?,?,?,?)");$q->execute([$public,$u['id'],$quote['subtotal_cents'],$quote['shipping_cents'],$quote['estimated_tax_cents'],$quote['total_cents'],$quote['shipping_method'],json_encode($shipping)]);$order=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO order_items(order_id,product_id,variant_id,name,size_us,colorway,finish,materials_json,quantity,price_cents) VALUES(?,?,?,?,?,?,?,?,?,?)');foreach($quote['lines'] as $l)$q->execute([$order,$l['product_id'],$l['variant_id'],$l['name'],$l['size'],$l['color'],$l['finish'],json_encode($l['materials']),$l['quantity'],$l['unit_cents']]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}json_response(['mode'=>'demo','order_id'=>$public,'message'=>'Demo order created. No payment charged or physical item shipped.','quote'=>$quote],201);
 }
 if($a==='orders'&&$method==='GET'){if(!$u)api_error('Sign in first',401);$q=$db->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$q->execute([$u['id']]);$orders=$q->fetchAll();$items=$db->prepare('SELECT name,size_us,colorway,quantity FROM order_items WHERE order_id=?');foreach($orders as &$o){$items->execute([$o['id']]);$o['items']=$items->fetchAll();}json_response($orders);}
 if(str_starts_with($a,'admin_')){demo_admin();
  if($a==='admin_dashboard'&&$method==='GET')json_response(['customers'=>(int)$db->query("SELECT count(*) FROM users WHERE role='customer'")->fetchColumn(),'order_count'=>(int)$db->query('SELECT count(*) FROM orders')->fetchColumn(),'revenue_cents'=>0,'products'=>(int)$db->query('SELECT count(*) FROM products')->fetchColumn()]);
  if($a==='admin_orders'&&$method==='GET'){$rows=$db->query('SELECT o.*,u.email customer_email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC')->fetchAll();foreach($rows as &$o)$o['shipping']=json_decode($o['shipping_json'],true);json_response($rows);}
  if($a==='admin_products'&&$method==='GET')json_response($db->query('SELECT p.sku,p.name,p.price_cents,p.active,v.id variant_id,v.size_us,v.colorway,v.stock FROM products p JOIN variants v ON v.product_id=p.id ORDER BY p.id,v.id')->fetchAll());
  if($a==='admin_settings') {if($method==='GET')json_response(['standard_cents'=>(int)demo_setting('standard_cents','1500'),'express_cents'=>(int)demo_setting('express_cents','2900'),'free_threshold_cents'=>(int)demo_setting('free_threshold_cents','15000'),'estimated_tax_rates'=>json_decode(demo_setting('estimated_tax_rates','{}'),true)]);$b=body_json();foreach(['standard_cents','express_cents','free_threshold_cents'] as $k){$n=filter_var($b[$k]??null,FILTER_VALIDATE_INT);if($n===false||$n<0||$n>100000)api_error('Invalid shipping amount');$db->prepare('UPDATE store_settings SET setting_value=? WHERE setting_key=?')->execute([(string)$n,$k]);}if(isset($b['estimated_tax_rates'])){if(!is_array($b['estimated_tax_rates']))api_error('Invalid rates');$rates=[];foreach($b['estimated_tax_rates'] as $k=>$v){if(!preg_match('/^[A-Z]{2}$/',$k)||!is_numeric($v)||(float)$v<0||(float)$v>.3)api_error('Invalid rate');$rates[$k]=(float)$v;}$db->prepare('UPDATE store_settings SET setting_value=? WHERE setting_key=?')->execute([json_encode($rates),'estimated_tax_rates']);}json_response(['saved'=>true]);}
  if($a==='admin_products'&&$method==='POST'){$b=body_json();$sku=(string)($b['sku']??'');$price=filter_var($b['price_cents']??null,FILTER_VALIDATE_INT);if($price===false||$price<0||$price>10000000)api_error('Invalid price');$db->prepare('UPDATE products SET price_cents=? WHERE sku=?')->execute([$price,$sku]);json_response(['saved'=>true]);}
  if($a==='admin_stock'&&$method==='POST'){$b=body_json();$id=filter_var($b['variant_id']??null,FILTER_VALIDATE_INT);$stock=filter_var($b['stock']??null,FILTER_VALIDATE_INT);if(!$id||$stock===false||$stock<0||$stock>99999)api_error('Invalid stock');$db->prepare('UPDATE variants SET stock=? WHERE id=?')->execute([$stock,$id]);json_response(['saved'=>true]);}
